32	#define INVALID_SCOPE -1
33	#define CUBE_SCOPE 0
34	#define VEC_SCOPE 1
35	
36	struct PipelineInfo {
37	  const ForNode *for_node;
38	  bool is_cross_core;
39	  int32_t scene;
40	  std::string loop_var_name;
41	};
42	
43	std::unordered_map<std::string, std::string> callnodeMapPos_ = {
44	    {"wmma.matrix_a", "cube"},    {"wmma.matrix_b", "cube"},
45	    {"wmma.accumulator", "cube"}, {"shared.l1", "cube"},
46	    {"shared.ub", "vec"},         {"local.var", "vec"}};
47	
48	int32_t checkBufferScope(Map<Var, String> location_map, const Var &var) {
49	  if (location_map.find(var) != location_map.end()) {
50	    if (callnodeMapPos_[location_map[var]] == "cube") {
51	      return CUBE_SCOPE;
52	    } else if (callnodeMapPos_[location_map[var]] == "vec") {
53	      return VEC_SCOPE;
54	    } else {
55	      return INVALID_SCOPE;
56	    }
57	  }
58	  return INVALID_SCOPE;
59	}
