61	class CrossCoreDetector : public StmtVisitor {
62	public:
63	  CrossCoreDetector(Map<Var, String> location_map)
64	      : location_map_(location_map) {}
65	
66	  std::vector<PipelineInfo> DetectCrossCorePipelines(const Stmt &stmt) {
67	    pipeline_infos_.clear();
68	    current_pipeline_info_ = nullptr;
69	    this->VisitStmt(stmt);
70	    std::vector<PipelineInfo> cross_core_pipelines;
71	    for (const auto &info : pipeline_infos_) {
72	      if (info.is_cross_core) {
73	        cross_core_pipelines.push_back(info);
74	      }
75	    }
76	    return cross_core_pipelines;
77	  }
78	
79	  void VisitStmt_(const ForNode *loop) override {
80	    auto num_stages_anno = loop->annotations.Get("num_stages");
81	    if (num_stages_anno.defined()) {
82	      PipelineInfo *prev_pipeline = current_pipeline_info_;
83	
84	      PipelineInfo new_info;
85	      new_info.for_node = loop;
86	      new_info.is_cross_core = false;
87	      new_info.scene = INVALID_SCOPE;
88	      new_info.loop_var_name = loop->loop_var->name_hint;
89	
90	      current_pipeline_info_ = &new_info;
91	      pipeline_infos_.push_back(new_info);
92	      this->VisitStmt(loop->body);
93	
94	      if (!pipeline_infos_.empty()) {
95	        pipeline_infos_.back() = new_info;
96	      }
97	      current_pipeline_info_ = prev_pipeline;
98	    } else {
99	      this->VisitStmt(loop->body);
100	    }
101	  }
102	
103	  void VisitStmt_(const EvaluateNode *op) override {
104	    if (!current_pipeline_info_) {
105	      return;
106	    }
107	
108	    auto call_node = op->value.as<CallNode>();
109	    auto scope = INVALID_SCOPE;
110	    for (int i = 1; i < call_node->args.size(); i++) {
111	      if (auto inner_node = call_node->args[i].as<CallNode>()) {
112	        auto buf_name = Downcast<Var>(inner_node->args[1]);
113	        scope = checkBufferScope(location_map_, buf_name);
114	        if (scope != INVALID_SCOPE) {
115	          break;
116	        }
117	      }
118	    }
119	    if (scope != INVALID_SCOPE) {
120	      if (current_pipeline_info_->scene == INVALID_SCOPE) {
121	        current_pipeline_info_->scene = scope;
122	      } else if (current_pipeline_info_->scene != scope) {
123	        current_pipeline_info_->is_cross_core = true;
124	      }
125	    }
126	  }
127	
128	private:
129	  std::vector<PipelineInfo> pipeline_infos_;
130	  Map<Var, String> location_map_;
131	  PipelineInfo *current_pipeline_info_{nullptr};
132	};
