134	class BufferMapTransformer {
135	public:
136	  BufferMapTransformer(const Map<Var, String> &location_map, int32_t num_stages)
137	      : location_map_(location_map), num_stages_(num_stages) {}
138	
139	  Map<Var, Buffer>
140	  TransformBufferMap(const Map<Var, Buffer> &original_buffer_map) {
141	    Map<Var, Buffer> resized_buffer;
142	    for (const auto &kv : original_buffer_map) {
143	      Var var = kv.first;
144	      Buffer old_buffer = kv.second;
145	      Buffer new_buffer = old_buffer;
146	
147	      if (IsWorkspaceBuffer(old_buffer)) {
148	        new_buffer = CreateResizedBuffer(old_buffer);
149	      }
150	      resized_buffer.Set(var, new_buffer);
151	    }
152	    return resized_buffer;
153	  }
154	
155	private:
156	  bool IsWorkspaceBuffer(const Buffer &buffer) {
157	    std::string name = buffer->name;
158	    if (name.find("workspace") != 0) {
159	      return false;
160	    }
161	    return true;
162	  }
163	
164	  Buffer CreateResizedBuffer(const Buffer &old_buffer) const {
165	    ObjectPtr<BufferNode> new_buffer =
166	        make_object<BufferNode>(*(old_buffer.get()));
167	    new_buffer->shape.insert(new_buffer->shape.begin(), PrimExpr(num_stages_));
168	    if (new_buffer->strides.size()) {
169	      ICHECK(new_buffer->strides.size() + 1 == new_buffer->shape.size());
170	      PrimExpr stride_0 = new_buffer->strides[0] * new_buffer->shape[1];
171	      new_buffer->strides.insert(new_buffer->strides.begin(), stride_0);
172	    }
173	    return Buffer(new_buffer);
174	  }
175	
176	private:
177	  Map<Var, String> location_map_;
178	  int32_t num_stages_;
179	};
