181	static int32_t DetectScope(const Stmt &stmt,
182	                           const Map<Var, String> &location_map) {
183	  if (const auto *eval = stmt.as<EvaluateNode>()) {
184	    if (const auto *call = eval->value.as<CallNode>()) {
185	      int start = call->op.same_as(builtin::call_extern()) ? 1 : 0;
186	      for (int i = start; i < static_cast<int>(call->args.size()); ++i) {
187	        if (const auto *inner = call->args[i].as<CallNode>()) {
188	          if (inner->args.size() >= 2) {
189	            if (auto buf_var = inner->args[1].as<VarNode>()) {
190	              Var var = GetRef<Var>(buf_var);
191	              int32_t scope = checkBufferScope(location_map, var);
192	              if (scope != INVALID_SCOPE)
193	                return scope;
194	            }
195	          }
196	        }
197	      }
198	    }
199	  } else if (const auto *store = stmt.as<BufferStoreNode>()) {
200	    Var buf_var = store->buffer->data;
201	    int32_t scope = checkBufferScope(location_map, buf_var);
202	    if (scope != INVALID_SCOPE)
203	      return scope;
204	  } else if (const auto *seq = stmt.as<SeqStmtNode>()) {
205	    for (const auto &s : seq->seq) {
206	      int32_t scope = DetectScope(s, location_map);
207	      if (scope != INVALID_SCOPE)
208	        return scope;
209	    }
210	  } else if (const auto *loop = stmt.as<ForNode>()) {
211	    return DetectScope(loop->body, location_map);
212	  } else if (const auto *ite = stmt.as<IfThenElseNode>()) {
213	    int32_t scope = DetectScope(ite->then_case, location_map);
214	    if (scope != INVALID_SCOPE)
215	      return scope;
216	    if (ite->else_case)
217	      return DetectScope(ite->else_case.value(), location_map);
218	  } else if (const auto *let = stmt.as<LetStmtNode>()) {
219	    return DetectScope(let->body, location_map);
220	  } else if (const auto *attr = stmt.as<AttrStmtNode>()) {
221	    return DetectScope(attr->body, location_map);
222	  } else if (const auto *realize = stmt.as<BlockRealizeNode>()) {
223	    return DetectScope(realize->block->body, location_map);
224	  }
225	  return INVALID_SCOPE;
226	}
