228	class LoopAnalyzer : public StmtVisitor {
229	public:
230	  /*!
231	   * \brief A single buffer access extracted from tvm_access_ptr(dtype, buf,
232	   * offset, extent, rw_mask).
233	   */
234	  struct AccessInfo {
235	    std::string buffer_name;
236	    PrimExpr offset;
237	    PrimExpr extent;
238	    bool is_read;
239	    bool is_write;
240	    int order;
241	  };
242	
243	  struct StmtInfo {
244	    int idx;
245	    std::string type;
246	    std::string buffer_name;
247	    Stmt stmt;
248	    std::set<std::string> used_buffers;
249	    std::vector<AccessInfo> accesses;
250	    int32_t scope{INVALID_SCOPE};
251	  };
252	
253	  struct WorkspaceWrite {
254	    int stmt_idx;
255	    std::string buffer_name;
256	    Call call;
257	  };
258	
259	  const std::vector<std::string> IS_WRITE_GM = {
260	      "copy_l0c_to_gm", "copy_ub_to_gm", "atomic_add_l0c_to_gm",
261	      "atomic_add_ub_to_gm"};
262	
263	  const std::vector<std::string> IS_PIPE_WRITE = {"copy_l0c_to_pipe",
264	                                                  "copy_ub_to_pipe"};
265	
266	  LoopAnalyzer(const ForNode *pipeline_loop,
267	               const Map<Var, String> location_map,
268	               const Map<IntImm, Map<String, ObjectRef>> &pipe_infos)
269	      : pipeline_loop_(pipeline_loop), location_map_(location_map),
270	        pipe_infos_(pipe_infos) {}
271	
272	  void Analyze() {
273	    all_statements_C_.clear();
274	    all_statements_V_.clear();
275	    all_statements_.clear();
276	    workspace_writes_C_.clear();
277	    workspace_writes_V_.clear();
278	    current_idx_C_ = 0;
279	    current_idx_V_ = 0;
280	    current_idx_ = 0;
281	    core_scope_ = INVALID_SCOPE;
282	    this->VisitStmt(pipeline_loop_->body);
283	  }
284	
285	  const std::vector<StmtInfo> &all_statements_C() const {
286	    return all_statements_C_;
287	  }
288	  const std::vector<StmtInfo> &all_statements_V() const {
289	    return all_statements_V_;
290	  }
291	  const std::vector<StmtInfo> &all_statements() const {
292	    return all_statements_;
293	  }
294	  const std::vector<WorkspaceWrite> &workspace_writes_C() const {
295	    return workspace_writes_C_;
296	  }
297	  const std::vector<WorkspaceWrite> &workspace_writes_V() const {
298	    return workspace_writes_V_;
299	  }
300	  const Map<Var, String> &location_map() const { return location_map_; }
301	
302	  void VisitStmt_(const SeqStmtNode *op) {
303	    for (const Stmt &stmt : op->seq) {
304	      this->VisitStmt(stmt);
305	    }
306	  }
307	
308	  void VisitStmt_(const EvaluateNode *op) {
309	    StmtInfo info;
310	    info.type = "Evaluate";
311	    info.stmt = GetRef<Stmt>(op);
312	    if (auto call_node = op->value.as<CallNode>()) {
313	      int arg_start = call_node->op.same_as(builtin::call_extern()) ? 1 : 0;
314	      for (int idx = arg_start; idx < call_node->args.size(); idx++) {
315	        if (auto inter_node = call_node->args[idx].as<CallNode>()) {
316	          auto buf_name = Downcast<Var>(inter_node->args[1]);
317	          core_scope_ = checkBufferScope(location_map_, buf_name);
318	          if (core_scope_ != INVALID_SCOPE) {
319	            break;
320	          }
321	        }
322	      }
323	      if (core_scope_ == CUBE_SCOPE) {
324	        info.idx = current_idx_C_++;
325	      } else if (core_scope_ == VEC_SCOPE) {
326	        info.idx = current_idx_V_++;
327	      }
328	      if (auto workspace_name = FindWorkspaceName(call_node)) {
329	        info.buffer_name = workspace_name.value();
330	      }
331	
332	      std::string normalized_name = "";
333	      if (call_node->op.same_as(builtin::call_extern())) {
334	        std::string func_name = call_node->args[0].as<StringImmNode>()->value;
335	        normalized_name = NormalizeFunctionName(func_name);
336	      } else {
337	        normalized_name = call_node->op.as<OpNode>()->name;
338	      }
339	
340	      bool is_gm_write = std::find(IS_WRITE_GM.begin(), IS_WRITE_GM.end(),
341	                                   normalized_name) != IS_WRITE_GM.end();
342	      bool is_pipe_write = std::find(IS_PIPE_WRITE.begin(), IS_PIPE_WRITE.end(),
343	                                     normalized_name) != IS_PIPE_WRITE.end();
344	
345	      if (is_gm_write || is_pipe_write) {
346	        WorkspaceWrite write;
347	        write.stmt_idx = info.idx;
348	
349	        if (is_gm_write) {
350	          if (auto workspace_name = FindWorkspaceName(call_node)) {
351	            write.buffer_name = workspace_name.value();
352	          }
353	        } else {
354	          if (auto flag_id = ExtractFlagId(call_node)) {
355	            if (auto workspace_name =
356	                    FindWorkspaceFromPipeInfos(flag_id.value())) {
357	              write.buffer_name = workspace_name.value();
358	            }
359	          }
360	        }
361	
362	        if (core_scope_ == CUBE_SCOPE) {
363	          workspace_writes_C_.push_back(write);
364	        } else if (core_scope_ == VEC_SCOPE) {
365	          workspace_writes_V_.push_back(write);
366	        }
367	      }
368	      CollectBuffersAndAccesses(call_node, info.used_buffers, info.accesses);
369	    }
370	    if (core_scope_ == CUBE_SCOPE) {
371	      all_statements_C_.push_back(info);
372	    } else if (core_scope_ == VEC_SCOPE) {
373	      all_statements_V_.push_back(info);
374	    }
375	    if (core_scope_ != INVALID_SCOPE) {
376	      info.idx = current_idx_++;
377	      info.scope = core_scope_;
378	      all_statements_.push_back(info);
379	    }
380	  }
381	
382	  void VisitStmt_(const BufferStoreNode *op) override {
383	    StmtInfo info;
384	    info.type = "BufferStore";
385	    info.stmt = GetRef<Stmt>(op);
386	
387	    Var buf_var = op->buffer->data;
388	    core_scope_ = checkBufferScope(location_map_, buf_var);
389	
390	    if (core_scope_ == CUBE_SCOPE) {
391	      info.idx = current_idx_C_++;
392	    } else if (core_scope_ == VEC_SCOPE) {
393	      info.idx = current_idx_V_++;
394	    }
395	
396	    std::string buf_name = buf_var->name_hint;
397	    if (location_map_.find(buf_var) != location_map_.end()) {
398	      info.used_buffers.insert(buf_name);
399	    }
400	
401	    CollectBuffersFromExpr(op->value, info.used_buffers, info.accesses);
402	
403	    AccessInfo access;
404	    access.buffer_name = buf_name;
405	    access.offset =
406	        op->indices.empty() ? make_zero(op->buffer->dtype) : op->indices[0];
407	    access.extent = make_const(DataType::Int(32), 1);
408	    access.is_read = false;
409	    access.is_write = true;
410	    access.order = static_cast<int>(info.accesses.size());
411	    info.accesses.push_back(access);
412	
413	    if (core_scope_ == CUBE_SCOPE) {
414	      all_statements_C_.push_back(info);
415	    } else if (core_scope_ == VEC_SCOPE) {
416	      all_statements_V_.push_back(info);
417	    }
418	    if (core_scope_ != INVALID_SCOPE) {
419	      info.idx = current_idx_++;
420	      info.scope = core_scope_;
421	      all_statements_.push_back(info);
422	    }
423	  }
424	
425	  void VisitStmt_(const ForNode *op) override {
426	    StmtInfo for_info;
427	    for_info.type = "For";
428	    for_info.stmt = GetRef<Stmt>(op);
429	
430	    std::vector<StmtInfo> saved_statements_C = all_statements_C_;
431	    std::vector<StmtInfo> saved_statements_V = all_statements_V_;
432	    std::vector<StmtInfo> saved_statements = all_statements_;
433	    int saved_idx_C = current_idx_C_;
434	    int saved_idx_V = current_idx_V_;
435	    int saved_idx = current_idx_;
436	
437	    this->VisitStmt(op->body);
438	
439	    bool has_new_C = saved_statements_C.size() < all_statements_C_.size();
440	    bool has_new_V = saved_statements_V.size() < all_statements_V_.size();
441	
442	    if (has_new_V) {
443	      ProcessInfo(workspace_writes_V_, all_statements_V_, saved_statements_V,
444	                  saved_idx_V, for_info);
445	      current_idx_V_ = all_statements_V_.size();
446	    }
447	    if (has_new_C) {
448	      ProcessInfo(workspace_writes_C_, all_statements_C_, saved_statements_C,
449	                  saved_idx_C, for_info);
450	      current_idx_C_ = all_statements_C_.size();
451	    }
452	    if (has_new_V || has_new_C) {
453	      StmtInfo unified_for_info = for_info;
454	      unified_for_info.scope = core_scope_;
455	      ProcessInfoUnified(all_statements_, saved_statements, saved_idx,
456	                         unified_for_info);
457	      current_idx_ = all_statements_.size();
458	    }
459	  }
460	
461	  void VisitStmt_(const BlockRealizeNode *op) override {
462	    this->VisitStmt(op->block);
463	  }
464	
465	  void VisitStmt_(const IfThenElseNode *op) override {
466	    StmtInfo ite_info;
467	    ite_info.type = "IfThenElse";
468	    ite_info.stmt = GetRef<Stmt>(op);
469	
470	    std::vector<StmtInfo> saved_statements_C = all_statements_C_;
471	    std::vector<StmtInfo> saved_statements_V = all_statements_V_;
472	    std::vector<StmtInfo> saved_statements = all_statements_;
473	    int saved_idx_C = current_idx_C_;
474	    int saved_idx_V = current_idx_V_;
475	    int saved_idx = current_idx_;
476	
477	    this->VisitStmt(op->then_case);
478	    if (op->else_case) {
479	      this->VisitStmt(op->else_case.value());
480	    }
481	
482	    int32_t then_scope = DetectScope(op->then_case, location_map_);
483	    int32_t else_scope = INVALID_SCOPE;
484	    if (op->else_case) {
485	      else_scope = DetectScope(op->else_case.value(), location_map_);
486	    }
487	
488	    int32_t ite_scope = (then_scope != INVALID_SCOPE) ? then_scope : else_scope;
489	    bool mixed_scope =
490	        (then_scope != INVALID_SCOPE && else_scope != INVALID_SCOPE &&
491	         then_scope != else_scope);
492	
493	    if (mixed_scope) {
494	    } else if (ite_scope != INVALID_SCOPE) {
495	      if (ite_scope == CUBE_SCOPE) {
496	        ProcessInfo(workspace_writes_C_, all_statements_C_, saved_statements_C,
497	                    saved_idx_C, ite_info);
498	        current_idx_C_ = all_statements_C_.size();
499	      } else {
500	        ProcessInfo(workspace_writes_V_, all_statements_V_, saved_statements_V,
501	                    saved_idx_V, ite_info);
502	        current_idx_V_ = all_statements_V_.size();
503	      }
504	
505	      CollectIfThenElseBuffers(op, ite_info.used_buffers, ite_info.accesses);
506	
507	      ite_info.scope = ite_scope;
508	      ite_info.idx = current_idx_++;
509	      all_statements_.push_back(ite_info);
510	    }
511	  }
512	
513	private:
514	  void CollectBuffersFromExpr(const PrimExpr &expr,
515	                              std::set<std::string> &used_buffers,
516	                              std::vector<AccessInfo> &accesses) {
517	    if (const auto *load = expr.as<BufferLoadNode>()) {
518	      Var buf_var = load->buffer->data;
519	      std::string buf_name = buf_var->name_hint;
520	      if (location_map_.find(buf_var) != location_map_.end()) {
521	        used_buffers.insert(buf_name);
522	        AccessInfo access;
523	        access.buffer_name = buf_name;
524	        access.offset = load->indices.empty() ? make_zero(load->buffer->dtype)
525	                                              : load->indices[0];
526	        access.extent = make_const(DataType::Int(32), 1);
527	        access.is_read = true;
528	        access.is_write = false;
529	        access.order = static_cast<int>(accesses.size());
530	        accesses.push_back(access);
531	      }
532	    } else if (const auto *call = expr.as<CallNode>()) {
533	      for (const auto &arg : call->args) {
534	        CollectBuffersFromExpr(arg, used_buffers, accesses);
535	      }
536	    } else if (const auto *binop = expr.as<AddNode>()) {
537	      CollectBuffersFromExpr(binop->a, used_buffers, accesses);
538	      CollectBuffersFromExpr(binop->b, used_buffers, accesses);
539	    } else if (const auto *binop = expr.as<SubNode>()) {
540	      CollectBuffersFromExpr(binop->a, used_buffers, accesses);
541	      CollectBuffersFromExpr(binop->b, used_buffers, accesses);
542	    } else if (const auto *binop = expr.as<MulNode>()) {
543	      CollectBuffersFromExpr(binop->a, used_buffers, accesses);
544	      CollectBuffersFromExpr(binop->b, used_buffers, accesses);
545	    } else if (const auto *binop = expr.as<DivNode>()) {
546	      CollectBuffersFromExpr(binop->a, used_buffers, accesses);
547	      CollectBuffersFromExpr(binop->b, used_buffers, accesses);
548	    } else if (const auto *cast = expr.as<CastNode>()) {
549	      CollectBuffersFromExpr(cast->value, used_buffers, accesses);
550	    } else if (const auto *select = expr.as<SelectNode>()) {
551	      CollectBuffersFromExpr(select->condition, used_buffers, accesses);
552	      CollectBuffersFromExpr(select->true_value, used_buffers, accesses);
553	      CollectBuffersFromExpr(select->false_value, used_buffers, accesses);
554	    }
555	  }
556	
557	  void CollectIfThenElseBuffers(const IfThenElseNode *op,
558	                                std::set<std::string> &used_buffers,
559	                                std::vector<AccessInfo> &accesses) {
560	    CollectBuffersFromStmt(op->then_case, used_buffers, accesses);
561	    if (op->else_case) {
562	      CollectBuffersFromStmt(op->else_case.value(), used_buffers, accesses);
563	    }
564	  }
565	
566	  void CollectBuffersFromStmt(const Stmt &stmt,
567	                              std::set<std::string> &used_buffers,
568	                              std::vector<AccessInfo> &accesses) {
569	    if (const auto *eval = stmt.as<EvaluateNode>()) {
570	      if (const auto *call = eval->value.as<CallNode>()) {
571	        CollectBuffersAndAccesses(call, used_buffers, accesses);
572	      }
573	    } else if (const auto *store = stmt.as<BufferStoreNode>()) {
574	      Var buf_var = store->buffer->data;
575	      std::string buf_name = buf_var->name_hint;
576	      if (location_map_.find(buf_var) != location_map_.end()) {
577	        used_buffers.insert(buf_name);
578	      }
579	      CollectBuffersFromExpr(store->value, used_buffers, accesses);
580	    } else if (const auto *seq = stmt.as<SeqStmtNode>()) {
581	      for (const auto &s : seq->seq) {
582	        CollectBuffersFromStmt(s, used_buffers, accesses);
583	      }
584	    } else if (const auto *loop = stmt.as<ForNode>()) {
585	      CollectBuffersFromStmt(loop->body, used_buffers, accesses);
586	    } else if (const auto *ite = stmt.as<IfThenElseNode>()) {
587	      CollectBuffersFromStmt(ite->then_case, used_buffers, accesses);
588	      if (ite->else_case) {
589	        CollectBuffersFromStmt(ite->else_case.value(), used_buffers, accesses);
590	      }
591	    } else if (const auto *let = stmt.as<LetStmtNode>()) {
592	      CollectBuffersFromStmt(let->body, used_buffers, accesses);
593	    } else if (const auto *attr = stmt.as<AttrStmtNode>()) {
594	      CollectBuffersFromStmt(attr->body, used_buffers, accesses);
595	    } else if (const auto *realize = stmt.as<BlockRealizeNode>()) {
596	      CollectBuffersFromStmt(realize->block->body, used_buffers, accesses);
597	    }
598	  }
