600	  void ProcessInfo(std::vector<WorkspaceWrite> &workspace_writes,
601	                   std::vector<StmtInfo> &all_statements,
602	                   std::vector<StmtInfo> &saved_statements, int saved_idx,
603	                   StmtInfo for_info) {
604	    for_info.idx = saved_idx++;
605	
606	    for (auto &write_info : workspace_writes) {
607	      if (write_info.stmt_idx > for_info.idx) {
608	        write_info.stmt_idx = for_info.idx;
609	      }
610	    }
611	
612	    std::set<std::string> for_node_buffers;
613	    std::vector<AccessInfo> for_node_accesses;
614	    for (size_t i = for_info.idx; i < all_statements.size(); i++) {
615	      auto buffers = all_statements[i].used_buffers;
616	      for (auto it = buffers.begin(); it != buffers.end(); ++it) {
617	        for_node_buffers.insert(*it);
618	      }
619	      for (const auto &access : all_statements[i].accesses) {
620	        for_node_accesses.push_back(access);
621	      }
622	    }
623	    all_statements = saved_statements;
624	    all_statements.push_back(for_info);
625	    all_statements.back().used_buffers = for_node_buffers;
626	    all_statements.back().accesses = for_node_accesses;
627	  }
