650	  void CollectBuffersAndAccesses(const CallNode *call_node,
651	                                 std::set<std::string> &used_buffers,
652	                                 std::vector<AccessInfo> &accesses) {
653	    auto args = call_node->args;
654	    int start = call_node->op.same_as(builtin::call_extern()) ? 1 : 0;
655	
656	    for (int i = start; i < args.size(); ++i) {
657	      if (auto inner_call_node = args[i].as<CallNode>()) {
658	        bool is_tvm_ap = inner_call_node->op.same_as(builtin::tvm_access_ptr());
659	        if (is_tvm_ap && inner_call_node->args.size() >= 5) {
660	          auto buf_var = Downcast<Var>(inner_call_node->args[1]);
661	          std::string buf_name = buf_var->name_hint;
662	          PrimExpr offset = inner_call_node->args[2];
663	          PrimExpr extent = inner_call_node->args[3];
664	          const IntImmNode *flag = inner_call_node->args[4].as<IntImmNode>();
665	          int rw_mask = flag ? static_cast<int>(flag->value) : 3;
666	
667	          bool found_in_map =
668	              location_map_.find(buf_var) != location_map_.end();
669	          bool found_in_pos = false;
670	          if (found_in_map) {
671	            found_in_pos = callnodeMapPos_.find(location_map_[buf_var]) !=
672	                           callnodeMapPos_.end();
673	          }
674	
675	          if (found_in_map && found_in_pos) {
676	            used_buffers.insert(buf_name);
677	          }
678	
679	          AccessInfo access;
680	          access.buffer_name = buf_name;
681	          access.offset = offset;
682	          access.extent = extent;
683	          access.is_read = (rw_mask & 1) != 0;
684	          access.is_write = (rw_mask & 2) != 0;
685	          access.order = static_cast<int>(accesses.size());
686	          accesses.push_back(access);
687	        } else {
688	          auto buf_name = Downcast<Var>(inner_call_node->args[1]);
689	          bool found = location_map_.find(buf_name) != location_map_.end();
690	          if (found) {
691	            if (callnodeMapPos_.find(location_map_[buf_name]) !=
692	                callnodeMapPos_.end()) {
693	              used_buffers.insert(buf_name->name_hint);
694	            }
695	          }
696	        }
697	      }
698	    }
699	  }
