773	/*!
774	 * \brief Check if [a_off, a_off+a_ext) ⊇ [b_off, b_off+b_ext).
775	 * Conservative: returns true only when provable from constant values.
776	 */
777	static bool RangeContains(const PrimExpr &a_off, const PrimExpr &a_ext,
778	                          const PrimExpr &b_off, const PrimExpr &b_ext) {
779	  auto a0 = a_off.as<IntImmNode>();
780	  auto a1 = a_ext.as<IntImmNode>();
781	  auto b0 = b_off.as<IntImmNode>();
782	  auto b1 = b_ext.as<IntImmNode>();
783	  if (a0 && a1 && b0 && b1) {
784	    return a0->value <= b0->value &&
785	           a0->value + a1->value >= b0->value + b1->value;
786	  }
787	  return false;
788	}
789	
790	/*!
791	 * \brief Check if [a_off, a_off+a_ext) ∩ [b_off, b_off+b_ext) ≠ ∅.
792	 * Conservative: returns true (assumes overlap) when non-constant.
793	 */
794	static bool RangeOverlaps(const PrimExpr &a_off, const PrimExpr &a_ext,
795	                          const PrimExpr &b_off, const PrimExpr &b_ext) {
796	  auto a0 = a_off.as<IntImmNode>();
797	  auto a1 = a_ext.as<IntImmNode>();
798	  auto b0 = b_off.as<IntImmNode>();
799	  auto b1 = b_ext.as<IntImmNode>();
800	  if (a0 && a1 && b0 && b1) {
801	    int64_t a_start = a0->value, a_end = a_start + a1->value;
802	    int64_t b_start = b0->value, b_end = b_start + b1->value;
803	    return a_start < b_end && b_start < a_end;
804	  }
805	  return true;
806	}
