808	/*!
809	 * \brief Collect all read ranges of a specific buffer from an AST subtree.
810	 */
811	static void
812	CollectBufferReadsFromExpr(const PrimExpr &expr, const std::string &target_buf,
813	                           std::vector<std::pair<PrimExpr, PrimExpr>> &reads) {
814	  if (const auto *load = expr.as<BufferLoadNode>()) {
815	    if (load->buffer->data->name_hint == target_buf) {
816	      PrimExpr offset = load->indices.empty() ? make_zero(load->buffer->dtype)
817	                                              : load->indices[0];
818	      reads.push_back({offset, make_const(DataType::Int(32), 1)});
819	    }
820	  } else if (const auto *call = expr.as<CallNode>()) {
821	    for (const auto &arg : call->args)
822	      CollectBufferReadsFromExpr(arg, target_buf, reads);
823	  } else if (const auto *binop = expr.as<AddNode>()) {
824	    CollectBufferReadsFromExpr(binop->a, target_buf, reads);
825	    CollectBufferReadsFromExpr(binop->b, target_buf, reads);
826	  } else if (const auto *binop = expr.as<SubNode>()) {
827	    CollectBufferReadsFromExpr(binop->a, target_buf, reads);
828	    CollectBufferReadsFromExpr(binop->b, target_buf, reads);
829	  } else if (const auto *binop = expr.as<MulNode>()) {
830	    CollectBufferReadsFromExpr(binop->a, target_buf, reads);
831	    CollectBufferReadsFromExpr(binop->b, target_buf, reads);
832	  } else if (const auto *binop = expr.as<DivNode>()) {
833	    CollectBufferReadsFromExpr(binop->a, target_buf, reads);
834	    CollectBufferReadsFromExpr(binop->b, target_buf, reads);
835	  } else if (const auto *cast = expr.as<CastNode>()) {
836	    CollectBufferReadsFromExpr(cast->value, target_buf, reads);
837	  } else if (const auto *select = expr.as<SelectNode>()) {
838	    CollectBufferReadsFromExpr(select->condition, target_buf, reads);
839	    CollectBufferReadsFromExpr(select->true_value, target_buf, reads);
840	    CollectBufferReadsFromExpr(select->false_value, target_buf, reads);
841	  }
842	}
843	
844	static void
845	CollectBufferReads(const Stmt &stmt, const std::string &target_buf,
846	                   std::vector<std::pair<PrimExpr, PrimExpr>> &reads) {
847	  if (const auto *eval = stmt.as<EvaluateNode>()) {
848	    if (const auto *call = eval->value.as<CallNode>()) {
849	      int start = call->op.same_as(builtin::call_extern()) ? 1 : 0;
850	      for (int i = start; i < static_cast<int>(call->args.size()); ++i) {
851	        if (const auto *inner = call->args[i].as<CallNode>()) {
852	          if (inner->op.same_as(builtin::tvm_access_ptr()) &&
853	              inner->args.size() >= 5) {
854	            auto buf_var = Downcast<Var>(inner->args[1]);
855	            if (buf_var->name_hint != target_buf)
856	              continue;
857	            const IntImmNode *flag = inner->args[4].as<IntImmNode>();
858	            int rw_mask = flag ? static_cast<int>(flag->value) : 3;
859	            if ((rw_mask & 1) != 0) {
860	              reads.push_back({inner->args[2], inner->args[3]});
861	            }
862	          }
863	        }
864	      }
865	    }
866	  } else if (const auto *store = stmt.as<BufferStoreNode>()) {
867	    CollectBufferReadsFromExpr(store->value, target_buf, reads);
868	  } else if (const auto *seq = stmt.as<SeqStmtNode>()) {
869	    for (const auto &s : seq->seq)
870	      CollectBufferReads(s, target_buf, reads);
871	  } else if (const auto *loop = stmt.as<ForNode>()) {
872	    CollectBufferReads(loop->body, target_buf, reads);
873	  } else if (const auto *ite = stmt.as<IfThenElseNode>()) {
874	    CollectBufferReads(ite->then_case, target_buf, reads);
875	    if (ite->else_case)
876	      CollectBufferReads(ite->else_case.value(), target_buf, reads);
877	  } else if (const auto *let = stmt.as<LetStmtNode>()) {
878	    CollectBufferReads(let->body, target_buf, reads);
879	  } else if (const auto *attr = stmt.as<AttrStmtNode>()) {
880	    CollectBufferReads(attr->body, target_buf, reads);
881	  } else if (const auto *realize = stmt.as<BlockRealizeNode>()) {
882	    CollectBufferReads(realize->block->body, target_buf, reads);
883	  }
884	}
