886	/*!
887	 * \brief Tree-based exposed read analysis.
888	 *
889	 * For a fixed target (buffer, offset, extent), traverses the AST to determine:
890	 *   - has_exposed_read: a read of the target range exists that is NOT preceded
891	 *     by a write covering the target range.
892	 *   - must_kill: this subtree definitely writes (covers) the target range.
893	 *
894	 * Composition rules:
895	 *   Sequential(A; B):  exposed = A.exposed || (!A.kill && B.exposed)
896	 *                      kill = A.kill || B.kill
897	 *   For(body):         exposed = body.exposed  (first iteration, no prior
898	 * kills) kill = body.kill If(then, else):    exposed = then.exposed ||
899	 * else.exposed kill = then.kill && else.kill Primitive:         exposed =
900	 * reads_target && !covered_from_above kill = writes_covering_target
901	 */
902	static std::pair<bool, bool> CheckExposedRead(const Stmt &stmt,
903	                                              const std::string &target_buf,
904	                                              const PrimExpr &target_offset,
905	                                              const PrimExpr &target_extent,
906	                                              bool covered) {
907	
908	  if (const auto *eval = stmt.as<EvaluateNode>()) {
909	    bool reads = false, kills = false;
910	    if (const auto *call = eval->value.as<CallNode>()) {
911	      int start = call->op.same_as(builtin::call_extern()) ? 1 : 0;
912	      for (int i = start; i < static_cast<int>(call->args.size()); ++i) {
913	        if (const auto *inner = call->args[i].as<CallNode>()) {
914	          if (inner->op.same_as(builtin::tvm_access_ptr()) &&
915	              inner->args.size() >= 5) {
916	            auto buf_var = Downcast<Var>(inner->args[1]);
917	            if (buf_var->name_hint != target_buf)
918	              continue;
919	            PrimExpr off = inner->args[2];
920	            PrimExpr ext = inner->args[3];
921	            const IntImmNode *flag = inner->args[4].as<IntImmNode>();
922	            int rw_mask = flag ? static_cast<int>(flag->value) : 3;
923	            if ((rw_mask & 1) != 0 &&
924	                RangeOverlaps(off, ext, target_offset, target_extent)) {
925	              reads = true;
926	            }
927	            if ((rw_mask & 2) != 0 &&
928	                RangeContains(off, ext, target_offset, target_extent)) {
929	              kills = true;
930	            }
931	          }
932	        }
933	      }
934	    }
935	    return {reads && !covered, kills};
936	  }
937	
938	  if (const auto *store = stmt.as<BufferStoreNode>()) {
939	    bool reads = false, kills = false;
940	    if (store->buffer->data->name_hint == target_buf) {
941	      PrimExpr off = store->indices.empty() ? make_zero(store->buffer->dtype)
942	                                            : store->indices[0];
943	      PrimExpr ext = make_const(DataType::Int(32), 1);
944	      if (RangeContains(off, ext, target_offset, target_extent)) {
945	        kills = true;
946	      }
947	    }
948	    std::function<bool(const PrimExpr &)> has_read = [&](const PrimExpr &expr) {
949	      if (const auto *load = expr.as<BufferLoadNode>()) {
950	        if (load->buffer->data->name_hint == target_buf) {
951	          PrimExpr off = load->indices.empty() ? make_zero(load->buffer->dtype)
952	                                               : load->indices[0];
953	          PrimExpr ext = make_const(DataType::Int(32), 1);
954	          return RangeOverlaps(off, ext, target_offset, target_extent);
955	        }
956	      } else if (const auto *call = expr.as<CallNode>()) {
957	        for (const auto &arg : call->args) {
958	          if (has_read(arg))
959	            return true;
960	        }
961	      } else if (const auto *binop = expr.as<AddNode>()) {
962	        return has_read(binop->a) || has_read(binop->b);
963	      } else if (const auto *binop = expr.as<SubNode>()) {
964	        return has_read(binop->a) || has_read(binop->b);
965	      } else if (const auto *binop = expr.as<MulNode>()) {
966	        return has_read(binop->a) || has_read(binop->b);
967	      } else if (const auto *binop = expr.as<DivNode>()) {
968	        return has_read(binop->a) || has_read(binop->b);
969	      } else if (const auto *cast = expr.as<CastNode>()) {
970	        return has_read(cast->value);
971	      } else if (const auto *select = expr.as<SelectNode>()) {
972	        return has_read(select->condition) || has_read(select->true_value) ||
973	               has_read(select->false_value);
974	      }
975	      return false;
976	    };
977	    reads = has_read(store->value);
978	    return {reads && !covered, kills};
979	  }
980	
981	  if (const auto *seq = stmt.as<SeqStmtNode>()) {
982	    bool any_exposed = false, any_kills = false;
983	    for (const auto &child : seq->seq) {
984	      auto [exp, kill] = CheckExposedRead(child, target_buf, target_offset,
985	                                          target_extent, covered || any_kills);
986	      any_exposed |= exp;
987	      any_kills |= kill;
988	    }
989	    return {any_exposed, any_kills};
990	  }
991	
992	  if (const auto *loop = stmt.as<ForNode>()) {
993	    return CheckExposedRead(loop->body, target_buf, target_offset,
994	                            target_extent, covered);
995	  }
996	
997	  if (const auto *ite = stmt.as<IfThenElseNode>()) {
998	    auto [t_exp, t_kill] = CheckExposedRead(
999	        ite->then_case, target_buf, target_offset, target_extent, covered);
1000	    if (ite->else_case) {
1001	      auto [e_exp, e_kill] =
1002	          CheckExposedRead(ite->else_case.value(), target_buf, target_offset,
1003	                           target_extent, covered);
1004	      return {t_exp || e_exp, t_kill && e_kill};
1005	    }
1006	    return {t_exp, false};
1007	  }
1008	
1009	  if (const auto *let = stmt.as<LetStmtNode>()) {
1010	    return CheckExposedRead(let->body, target_buf, target_offset, target_extent,
1011	                            covered);
1012	  }
1013	  if (const auto *attr = stmt.as<AttrStmtNode>()) {
1014	    return CheckExposedRead(attr->body, target_buf, target_offset,
1015	                            target_extent, covered);
1016	  }
1017	  if (const auto *realize = stmt.as<BlockRealizeNode>()) {
1018	    return CheckExposedRead(realize->block->body, target_buf, target_offset,
1019	                            target_extent, covered);
1020	  }
1021	
1022	  return {false, false};
1023	}
