1032	  LoopRewriter(const LoopAnalyzer &analyzer, const ForNode *original_loop,
1033	               int num_stages, int cross_interval = 1)
1034	      : analyzer_(analyzer), original_loop_(original_loop),
1035	        all_statements_(analyzer.all_statements()), num_stages_(num_stages),
1036	        cross_interval_(cross_interval) {
1037	    original_loop_var_ = original_loop->loop_var;
1038	    std::string outer_var_name = original_loop_var_->name_hint + "_outer";
1039	    outer_loop_var_ = Var(outer_var_name, original_loop_var_->dtype);
1040	    stage_loop_var_ = Var("i", DataType::Int(32));
