1043	  Stmt Rewrite() {
1044	    std::vector<StageInfo> stages = SplitIntoStages();
1045	    AnalyzeSharedBuffers(stages);
1046	    return CreateStagedLoops(stages);
1047	  }
1048	
1049	  const std::set<std::string> &shared_buffers() const {
1050	    return shared_buffers_;
1051	  }
