1053	  const Var &outer_loop_var() const { return outer_loop_var_; }
1054	
1055	  std::set<std::string> GetAllBuffersToAdjust() const {
1056	    std::set<std::string> all_buffers = shared_buffers_;
1057	    for (const auto &stmt_info : all_statements_) {
1058	      if (!stmt_info.buffer_name.empty() &&
1059	          stmt_info.buffer_name.find("workspace") != std::string::npos) {
1060	        all_buffers.insert(stmt_info.buffer_name);
1061	      }
1062	    }
1063	    return all_buffers;
1064	  }
