1067	  Stmt CreateStagedLoops(const std::vector<StageInfo> &stages) {
1068	    Array<Stmt> stage_loops;
1069	    for (size_t stage_idx = 0; stage_idx < stages.size(); ++stage_idx) {
1070	      const auto &stage = stages[stage_idx];
1071	      Stmt stage_body = CreateStageBody(stage.statements);
1072	      Stmt stage_loop = CreateStageLoopWithBinding(stage_body);
1073	      stage_loops.push_back(stage_loop);
1074	    }
1075	    if (stage_loops.size() == 1) {
1076	      return stage_loops[0];
1077	    } else {
1078	      return SeqStmt(stage_loops);
1079	    }
1080	  }
1081	
1082	  Stmt CreateStageBody(const std::vector<LoopAnalyzer::StmtInfo> &statements) {
1083	    if (statements.empty()) {
1084	      return Stmt();
1085	    }
1086	    if (statements.size() == 1) {
1087	      return statements[0].stmt;
1088	    }
1089	    Array<Stmt> seq;
1090	    for (const auto &stmt_info : statements) {
1091	      seq.push_back(stmt_info.stmt);
1092	    }
1093	    return SeqStmt(seq);
1094	  }
