1096	  Stmt AddLetStmtBinding(const Stmt &body) {
1097	    PrimExpr binding_expr =
1098	        outer_loop_var_ * make_const(outer_loop_var_.dtype(), num_stages_) +
1099	        stage_loop_var_;
1100	    std::string transformed_var_name =
1101	        original_loop_var_->name_hint + "_transformed";
1102	    Var transformed_var(transformed_var_name, original_loop_var_->dtype);
1103	
1104	    class VarReplacer : public StmtExprMutator {
1105	    public:
1106	      VarReplacer(const Var &old_var, const Var &new_var)
1107	          : old_var_(old_var), new_var_(new_var) {}
1108	
1109	      PrimExpr VisitExpr_(const VarNode *op) override {
1110	        if (op->name_hint == old_var_->name_hint) {
1111	          return new_var_;
1112	        }
1113	        return GetRef<PrimExpr>(op);
1114	      }
1115	
1116	    private:
1117	      const Var &old_var_;
1118	      const Var &new_var_;
1119	    };
1120	
1121	    VarReplacer replacer(original_loop_var_, transformed_var);
1122	    Stmt new_body = replacer(body);
1123	
1124	    return LetStmt(transformed_var, binding_expr, new_body);
1125	  }
