1127	  Stmt CreateStageLoopWithBinding(const Stmt &body) {
1128	    PrimExpr min = make_const(DataType::Int(32), 0);
1129	    PrimExpr extent = make_const(DataType::Int(32), num_stages_);
1130	    Stmt loop_body = AddLetStmtBinding(body);
1131	
1132	    Map<String, ObjectRef> annotations;
1133	    annotations.Set("stage_loop", Bool(true));
1134	    annotations.Set("tl_cross_interval", PrimExpr(cross_interval_));
1135	    annotations.Set("tl_original_loop_var", original_loop_var_);
1136	
1137	    return For(stage_loop_var_, min, extent, ForKind::kSerial, loop_body,
1138	               original_loop_->thread_binding, annotations,
1139	               original_loop_->span);
1140	  }
