1142	  std::vector<StageInfo> SplitIntoStages() {
1143	    std::vector<StageInfo> stages;
1144	    if (all_statements_.empty())
1145	      return stages;
1146	
1147	    StageInfo current_stage;
1148	    int32_t current_scope = all_statements_[0].scope;
1149	
1150	    for (const auto &stmt_info : all_statements_) {
1151	      if (stmt_info.scope != current_scope) {
1152	        if (!current_stage.statements.empty()) {
1153	          stages.push_back(current_stage);
1154	          current_stage = StageInfo();
1155	        }
1156	        current_scope = stmt_info.scope;
1157	      }
1158	      current_stage.statements.push_back(stmt_info);
1159	      for (const auto &buffer : stmt_info.used_buffers) {
1160	        current_stage.used_buffers.insert(buffer);
1161	      }
1162	    }
1163	    if (!current_stage.statements.empty()) {
1164	      stages.push_back(current_stage);
1165	    }
1166	
1167	    return stages;
1168	  }
