1170	  int32_t checkBufferScope(const std::string &buffer) {
1171	    for (const auto &pair : analyzer_.location_map()) {
1172	      if (pair.first.get()->name_hint == buffer) {
1173	        std::string scope_str = pair.second;
1174	        auto it = callnodeMapPos_.find(scope_str);
1175	        if (it != callnodeMapPos_.end()) {
1176	          if (it->second == "cube") {
1177	            return CUBE_SCOPE;
1178	          } else if (it->second == "vec") {
1179	            return VEC_SCOPE;
1180	          }
1181	        }
1182	        return INVALID_SCOPE;
1183	      }
1184	    }
1185	    return INVALID_SCOPE;
1186	  }
1187	
1188	  Stmt ReconstructStageBody(const StageInfo &stage) const {
1189	    if (stage.statements.size() == 1)
1190	      return stage.statements[0].stmt;
1191	    Array<Stmt> seq;
1192	    for (const auto &s : stage.statements)
1193	      seq.push_back(s.stmt);
1194	    return SeqStmt(seq);
1195	  }
1196	
1197	  void AnalyzeSharedBuffers(const std::vector<StageInfo> &stages) {
1198	    std::unordered_map<std::string, std::vector<int>> buffer_stage_map;
1199	    for (size_t stage_idx = 0; stage_idx < stages.size(); ++stage_idx) {
1200	      for (const auto &buffer : stages[stage_idx].used_buffers) {
1201	        buffer_stage_map[buffer].push_back(stage_idx);
1202	      }
1203	    }
1204	
1205	    for (const auto &[buffer, stage_indices] : buffer_stage_map) {
1206	      if (stage_indices.size() <= 1) {
1207	        continue;
1208	      }
1209	      bool is_shared = false;
1210	      for (int si : stage_indices) {
1211	        Stmt stage_body = ReconstructStageBody(stages[si]);
1212	
1213	        std::vector<std::pair<PrimExpr, PrimExpr>> reads;
1214	        CollectBufferReads(stage_body, buffer, reads);
1215	
1216	        for (const auto &[offset, extent] : reads) {
1217	          auto [exposed, kill] =
1218	              CheckExposedRead(stage_body, buffer, offset, extent, false);
1219	          if (exposed) {
1220	            is_shared = true;
1221	            break;
1222	          }
1223	        }
1224	        if (is_shared)
1225	          break;
1226	      }
1227	
1228	      if (is_shared) {
1229	        shared_buffers_.insert(buffer);
1230	      }
1231	    }
1232	  }
