1246	class CrossCorePipeline : public arith::IRMutatorWithAnalyzer {
1247	public:
1248	  static PrimFunc Substitute(PrimFunc f, PassContext ctx) {
1249	    arith::Analyzer analyzer;
1250	    CrossCorePipeline substituter(&analyzer);
1251	
1252	    return substituter.Transform(std::move(f), ctx);
1253	  }
1254	
1255	  PrimFunc Transform(PrimFunc f, PassContext ctx) {
1256	    PrimFuncNode *fptr = f.CopyOnWrite();
1257	
1258	    if (auto opt =
1259	            f->GetAttr<Map<IntImm, Map<String, ObjectRef>>>("pipe_infos")) {
1260	      pipe_infos_ = opt.value();
1261	    }
1262	    if (auto opt = f->GetAttr<String>("npu_platform")) {
1263	      platform_ = opt.value()->data;
1264	    } else {
1265	      platform_ = "A3";
1266	    }
1267	
1268	    tir::PostOrderVisit(f->body, [&](const ObjectRef &obj) {
1269	      if (const auto *realize = obj.as<tir::BlockRealizeNode>()) {
1270	        for (auto buf : realize->block->alloc_buffers) {
1271	          String scope = GetPtrStorageScope(buf->data);
1272	          location_map_.Set(buf->data, scope);
1273	        }
1274	      }
1275	    });
1276	
1277	    CrossCoreDetector detector(location_map_);
1278	    cross_core_pipelines_ = detector.DetectCrossCorePipelines(fptr->body);
1279	    if (cross_core_pipelines_.empty()) {
1280	      return f;
1281	    }
1282	
1283	    ICHECK(cross_core_pipelines_.size() == 1)
1284	        << "Cross_core_pipeline: only support one cross core pipeline body, "
1285	           "but got "
1286	        << cross_core_pipelines_.size();
1287	
1288	    const auto info = cross_core_pipelines_[0];
1289	    auto num_stages_anno = info.for_node->annotations.Get("num_stages");
1290	    int num_stages = num_stages_anno.as<IntImmNode>()->value;
1291	
1292	    BufferMapTransformer buffer_transformer(location_map_, num_stages);
1293	    origin_map_ = fptr->buffer_map;
1294	    auto buffer_result =
1295	        buffer_transformer.TransformBufferMap(fptr->buffer_map);
1296	    fptr->buffer_map = buffer_result;
1297	    fptr->body = this->VisitStmt(fptr->body);
1298	
1299	    auto fn_attr = fptr->attrs.CopyOnWrite();
1300	    fn_attr->dict.Set("buffer_versions", collected_buffer_versions_);
1301	    if (!pipe_infos_.empty()) {
1302	      fn_attr->dict.Set("pipe_infos", pipe_infos_);
1303	    }
1304	
1305	    return f;
1306	  }
1307	
1308	private:
1309	  using arith::IRMutatorWithAnalyzer::IRMutatorWithAnalyzer;
1310	
1311	  Stmt VisitStmt_(const ForNode *op) override {
1312	    if (op == cross_core_pipelines_[0].for_node) {
1313	      return ProcessCrossCorePipeline(op);
1314	    }
1315	    return arith::IRMutatorWithAnalyzer::VisitStmt_(op);
1316	  }
1317	
1318	  Stmt ProcessCrossCorePipeline(const ForNode *pipeline) {
1319	    LoopAnalyzer analyzer(pipeline, location_map_, pipe_infos_);
1320	    analyzer.Analyze();
1321	    if (analyzer.workspace_writes_C().empty() &&
1322	        analyzer.workspace_writes_V().empty()) {
1323	      return arith::IRMutatorWithAnalyzer::VisitStmt_(pipeline);
1324	    }
1325	
1326	    auto num_stages_anno = pipeline->annotations.Get("num_stages");
1327	    int num_stages = num_stages_anno.as<IntImmNode>()->value;
1328	    auto cross_interval_anno = pipeline->annotations.Get("tl_cross_interval");
1329	    int cross_interval = cross_interval_anno.defined()
1330	                             ? cross_interval_anno.as<IntImmNode>()->value
1331	                             : 1;
1332	    LoopRewriter rewriter(analyzer, pipeline, num_stages, cross_interval);
1333	    Stmt staged_loops = rewriter.Rewrite();
1334	    const Var &outer_loop_var = rewriter.outer_loop_var();
1335	    Stmt outer_loop =
1336	        ModifyOuterLoop(pipeline, staged_loops, num_stages, outer_loop_var);
1337	
1338	    if (platform_ != "A5") {
1339	      std::set<std::string> buffers_to_adjust =
1340	          rewriter.GetAllBuffersToAdjust();
1341	      if (!buffers_to_adjust.empty()) {
1342	        // Build a combined buffer map that includes both function params
1343	        // (origin_map_) and locally allocated buffers (alloc_buffers), so
1344	        // AdjustBuffersAndAccess can look up shapes for on-chip buffers like
1345	        // r_factors, sumexp_is, etc.
1346	        Map<Var, Buffer> combined_map(origin_map_);
1347	        if (const BlockRealizeNode *realize =
1348	                pipeline->body.as<BlockRealizeNode>()) {
1349	          for (const auto &buf : realize->block->alloc_buffers) {
1350	            combined_map.Set(buf->data, buf);
1351	          }
1352	        }
1353	        outer_loop = AdjustBuffersAndAccess(combined_map, outer_loop,
1354	                                            buffers_to_adjust, num_stages);
1355	      }
1356	    }
1357	
1358	    if (const BlockRealizeNode *original_realize =
1359	            pipeline->body.as<BlockRealizeNode>()) {
1360	      const BlockNode *original_block = original_realize->block.as<BlockNode>();
1361	      if (original_block) {
1362	        auto new_block = make_object<BlockNode>(*original_block);
1363	        new_block->body = outer_loop;
1364	        const auto &shared_buffers = rewriter.shared_buffers();
1365	        Block extended_block =
1366	            ExtendAllBuffers(Block(new_block), num_stages, shared_buffers);
1367	        auto extended_block_node = extended_block.CopyOnWrite();
1368	        extended_block_node->body = outer_loop;
1369	        Stmt new_realize =
1370	            BlockRealize(original_realize->iter_values,
1371	                         original_realize->predicate, extended_block);
1372	
1373	        if (!pipe_infos_.empty()) {
1374	          UpdatePipeInfosSlotNum(num_stages);
1375	        }
1376	
1377	        return this->VisitStmt(new_realize);
1378	      }
1379	    }
1380	    return this->VisitStmt(outer_loop);
1381	  }
1382	
1383	  void UpdatePipeInfosSlotNum(int num_stages) {
1384	    Map<IntImm, Map<String, ObjectRef>> new_pipe_infos;
1385	    for (const auto &[key, fields] : pipe_infos_) {
1386	      Map<String, ObjectRef> new_fields;
1387	      for (const auto &[field_key, field_value] : fields) {
1388	        if (field_key == "slot_num") {
1389	          int old_slot_num = Downcast<IntImm>(field_value)->value;
1390	          new_fields.Set(field_key,
1391	                         IntImm(DataType::Int(32), old_slot_num * num_stages));
1392	        } else {
1393	          new_fields.Set(field_key, field_value);
1394	        }
1395	      }
1396	      new_pipe_infos.Set(key, new_fields);
1397	    }
1398	    pipe_infos_ = new_pipe_infos;
1399	  }
1400	
1401	  Block ExtendAllBuffers(const Block &block, int num_stages,
1402	                         const std::set<std::string> &shared_buffers) {
1403	    ObjectPtr<BlockNode> new_block = make_object<BlockNode>(*block.get());
1404	
1405	    if (!new_block->alloc_buffers.empty()) {
1406	      Array<Buffer> new_alloc_buffers;
1407	
1408	      for (const auto &buffer : new_block->alloc_buffers) {
1409	        std::string name = buffer->name;
1410	        bool is_workspace = name.find("workspace") != std::string::npos;
1411	        bool is_shared_buffer =
1412	            shared_buffers.find(name) != shared_buffers.end();
1413	
1414	        if (is_workspace || is_shared_buffer) {
1415	          ObjectPtr<BufferNode> extended_buffer =
1416	              make_object<BufferNode>(*buffer.get());
1417	
1418	          if (!extended_buffer->shape.empty()) {
1419	            Array<PrimExpr> new_shape = extended_buffer->shape;
1420	            new_shape.insert(new_shape.begin(), PrimExpr(num_stages));
1421	            extended_buffer->shape = new_shape;
1422	          }
1423	
1424	          this->collected_buffer_versions_.Set(extended_buffer->data,
1425	                                               PrimExpr(num_stages));
1426	
1427	          new_alloc_buffers.push_back(Buffer(extended_buffer));
1428	        } else {
1429	          new_alloc_buffers.push_back(buffer);
1430	        }
1431	      }
1432	      new_block->alloc_buffers = new_alloc_buffers;
1433	    }
1434	    return Block(new_block);
1435	  }
