1437	  Stmt AdjustBuffersAndAccess(Map<Var, Buffer> origin_map, const Stmt &stmt,
1438	                              const std::set<std::string> &buffers_to_adjust,
1439	                              int num_stages) {
1440	    class BufferAccessAdjuster : public StmtExprMutator {
1441	    public:
1442	      BufferAccessAdjuster(Map<Var, Buffer> origin_map,
1443	                           const std::set<std::string> &buffers_to_adjust,
1444	                           int num_stages)
1445	          : origin_map_(origin_map), buffers_to_adjust_(buffers_to_adjust),
1446	            num_stages_(num_stages) {}
1447	
1448	      Stmt VisitStmt_(const ForNode *op) override {
1449	        if (op->annotations.Get("stage_loop")) {
1450	          stage_var_ = op->loop_var;
1451	          stage_idx_ = 0;
1452	          Stmt new_body = this->VisitStmt(op->body);
1453	          stage_var_ = Var();
1454	          return For(op->loop_var, op->min, op->extent, op->kind, new_body,
1455	                     op->thread_binding, op->annotations, op->span);
1456	        }
1457	        return StmtMutator::VisitStmt_(op);
1458	      }
1459	
1460	      Stmt VisitStmt_(const EvaluateNode *op) override {
1461	        if (stage_var_.defined()) {
1462	          stage_idx_++;
1463	        }
1464	
1465	        if (const CallNode *call = op->value.as<CallNode>()) {
1466	          Array<PrimExpr> new_args =
1467	              AdjustCallArgs(origin_map_, call->args, call);
1468	          if (new_args.size() > 0) {
1469	            if (call->op.same_as(tl::ascend_muls()) ||
1470	                call->op.same_as(tl::ascend_adds())) {
1471	              if (const CallNode *scalar_call = new_args[2].as<CallNode>()) {
1472	                if (const VarNode *var = scalar_call->args[1].as<VarNode>()) {
1473	                  std::string buffer_name = var->name_hint;
1474	                  if (buffers_to_adjust_.find(buffer_name) !=
1475	                      buffers_to_adjust_.end()) {
1476	                    PrimExpr scalar_offset = scalar_call->args[2];
1477	                    new_args.Set(3, new_args[3] + scalar_offset);
1478	                  }
1479	                }
1480	              }
1481	            }
1482	            Call new_call(call->dtype, call->op, new_args, call->span);
1483	            return Evaluate(new_call);
1484	          }
1485	        }
1486	        return StmtMutator::VisitStmt_(op);
1487	      }
1488	
1489	      Stmt VisitStmt_(const BufferStoreNode *op) override {
1490	        if (stage_var_.defined()) {
1491	          stage_idx_++;
1492	        }
1493	
1494	        BufferStore store = Downcast<BufferStore>(StmtMutator::VisitStmt_(op));
1495	
1496	        std::string buf_name = store->buffer->data->name_hint;
1497	        bool is_shared_buffer =
1498	            buffers_to_adjust_.find(buf_name) != buffers_to_adjust_.end();
1499	        bool is_workspace_buffer =
1500	            buf_name.find("workspace") != std::string::npos;
1501	
1502	        if ((is_shared_buffer || is_workspace_buffer) && stage_var_.defined()) {
1503	          for (auto &kv : origin_map_) {
1504	            Buffer buffer = kv.second;
1505	            if (buffer->name == buf_name) {
1506	              PrimExpr total_size = 1;
1507	              for (int i = 0; i < static_cast<int>(buffer->shape.size()); ++i) {
1508	                total_size = total_size * buffer->shape[i];
1509	              }
1510	              Array<PrimExpr> new_indices = store->indices;
1511	              if (!new_indices.empty()) {
1512	                new_indices.Set(0, new_indices[0] + stage_var_ * total_size);
1513	              }
1514	              return BufferStore(store->buffer, store->value, new_indices,
1515	                                 store->span);
1516	            }
1517	          }
1518	        }
1519	
1520	        return store;
1521	      }
1522	
1523	      PrimExpr VisitExpr_(const BufferLoadNode *op) override {
1524	        BufferLoad load = GetRef<BufferLoad>(op);
1525	
1526	        std::string buf_name = load->buffer->data->name_hint;
1527	        bool is_shared_buffer =
1528	            buffers_to_adjust_.find(buf_name) != buffers_to_adjust_.end();
1529	        bool is_workspace_buffer =
1530	            buf_name.find("workspace") != std::string::npos;
1531	
1532	        if ((is_shared_buffer || is_workspace_buffer) && stage_var_.defined()) {
1533	          for (auto &kv : origin_map_) {
1534	            Buffer buffer = kv.second;
1535	            if (buffer->name == buf_name) {
1536	              PrimExpr total_size = 1;
1537	              for (int i = 0; i < static_cast<int>(buffer->shape.size()); ++i) {
1538	                total_size = total_size * buffer->shape[i];
1539	              }
1540	              Array<PrimExpr> new_indices = load->indices;
1541	              if (!new_indices.empty()) {
1542	                new_indices.Set(0, new_indices[0] + stage_var_ * total_size);
1543	              }
1544	              return BufferLoad(load->buffer, new_indices, load->span);
1545	            }
1546	          }
1547	        }
1548	
1549	        return load;
1550	      }
