1552	    private:
1553	      Array<PrimExpr> AdjustCallArgs(Map<Var, Buffer> origin_map,
1554	                                     const Array<PrimExpr> &args,
1555	                                     const CallNode *parent_call) {
1556	        Array<PrimExpr> new_args;
1557	        bool modified = false;
1558	        PrimExpr i_value = stage_var_;
1559	
1560	        for (const auto &arg : args) {
1561	          if (const CallNode *inner_call = arg.as<CallNode>()) {
1562	            if (inner_call->op.same_as(builtin::tvm_access_ptr())) {
1563	              if (inner_call->args.size() >= 2) {
1564	                if (const VarNode *var = inner_call->args[1].as<VarNode>()) {
1565	                  std::string buffer_name = var->name_hint;
1566	                  bool is_shared_buffer =
1567	                      buffers_to_adjust_.find(buffer_name) !=
1568	                      buffers_to_adjust_.end();
1569	                  bool is_workspace_buffer =
1570	                      buffer_name.find("workspace") != std::string::npos;
1571	
1572	                  if (is_shared_buffer || is_workspace_buffer) {
1573	                    Array<PrimExpr> new_inner_args;
1574	                    new_inner_args.push_back(inner_call->args[0]);
1575	                    new_inner_args.push_back(inner_call->args[1]);
1576	
1577	                    if (inner_call->args.size() >= 3) {
1578	                      PrimExpr original_offset = inner_call->args[2];
1579	                      PrimExpr new_offset = original_offset;
1580	
1581	                      if (stage_var_.defined()) {
1582	                        if (is_shared_buffer || is_workspace_buffer) {
1583	                          for (auto &kv : origin_map) {
1584	                            Buffer buffer = kv.second;
1585	                            if (buffer->name == buffer_name) {
1586	                              PrimExpr total_size = 1;
1587	                              for (int i = 0;
1588	                                   i < static_cast<int>(buffer->shape.size());
1589	                                   ++i) {
1590	                                total_size = total_size * buffer->shape[i];
1591	                              }
1592	                              new_offset =
1593	                                  original_offset + i_value * total_size;
1594	                              break;
1595	                            }
1596	                          }
1597	                        }
1598	                      }
1599	                      new_inner_args.push_back(new_offset);
1600	                      for (size_t i = 3; i < inner_call->args.size(); ++i) {
1601	                        new_inner_args.push_back(inner_call->args[i]);
1602	                      }
1603	                      Call new_inner_call(inner_call->dtype, inner_call->op,
1604	                                          new_inner_args, inner_call->span);
1605	                      new_args.push_back(new_inner_call);
1606	                      modified = true;
1607	                      continue;
1608	                    }
1609	                  }
1610	                }
1611	              }
1612	            }
1613	          }
1614	          new_args.push_back(arg);
1615	        }
1616	        return modified ? new_args : Array<PrimExpr>();
1617	      }
1618	
1619	    private:
1620	      const std::set<std::string> &buffers_to_adjust_;
1621	      Map<Var, Buffer> origin_map_;
1622	      int num_stages_;
1623	      Var stage_var_;
1624	      int stage_idx_;
1625	    };
1626	    BufferAccessAdjuster adjuster(origin_map, buffers_to_adjust, num_stages);
1627	    return adjuster(stmt);
1628	  }
1629	
1630	  Stmt ModifyOuterLoop(const ForNode *pipeline, const Stmt &inner_loops,
1631	                       int num_stages, const Var &outer_loop_var) {
1632	    PrimExpr original_extent = pipeline->extent;
1633	    PrimExpr new_extent;
1634	    if (auto int_imm = original_extent.as<IntImmNode>()) {
1635	      int loop = int_imm->value;
1636	      new_extent = make_const(original_extent.dtype(), loop / num_stages);
1637	    } else {
1638	      new_extent =
1639	          original_extent * make_const(original_extent.dtype(), num_stages);
1640	    }
1641	
1642	    Map<String, ObjectRef> annotations;
1643	    annotations.Set("tl_original_extent", original_extent);
1644	
1645	    return For(outer_loop_var, pipeline->min, new_extent, ForKind::kSerial,
1646	               inner_loops, pipeline->thread_binding, annotations,
1647	               pipeline->span);
1648	  }
1649	
1650	private:
1651	  Map<Var, String> location_map_;
1652	  Map<Var, Buffer> origin_map_;
1653	  std::vector<PipelineInfo> cross_core_pipelines_;
1654	  Map<Var, PrimExpr> collected_buffer_versions_;
1655	  Map<IntImm, Map<String, ObjectRef>> pipe_infos_;
1656	  std::string platform_;
1657	};
1658	
1659	tvm::transform::Pass CrossCorePipeline() {
1660	  auto pass_func = [=](PrimFunc f, IRModule m, PassContext ctx) {
1661	    auto new_func = CrossCorePipeline::Substitute(std::move(f), ctx);
1662	    return new_func;
1663	  };
1664	  return CreatePrimFuncPass(pass_func, 0, "tl.CrossCorePipeline", {});
1665	}
1666	
1667	// regist host path
1668	TVM_REGISTER_GLOBAL("tl.transform.CrossCorePipeline")
1669	    .set_body_typed(CrossCorePipeline);
1670	} // namespace tl
1671	} // namespace tvm
